import FreeCAD

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")
print("Document opened:", doc.Name)

# Check for a2p constraint objects
for obj in doc.Objects:
    print(f"\n=== Object: {obj.Name} ===")
    print(f"  Label: {obj.Label}")
    print(f"  TypeId: {obj.TypeId}")

    # Check properties relevant to a2p
    if hasattr(obj, 'fixedPosition'):
        print(f"  fixedPosition: {obj.fixedPosition}")
    if hasattr(obj, 'ShapeMaterial'):
        print(f"  ShapeMaterial: {obj.ShapeMaterial}")

    # List all properties
    props = obj.PropertiesList
    for prop in props:
        try:
            val = getattr(obj, prop)
            if not callable(val):
                print(f"    {prop}: {val}")
        except Exception as e:
            print(f"    {prop}: <error getting value: {e}>")
